def caesar_cipher(text, shift):
    cipher = ''
    for char in text:
        if char.isalpha():
            code = ord(char) + shift
            if char.isupper():
                if code > 90:
                    code = 65 + (code - 91)
                elif code < 65:
                    code = 90 - (64 - code)
            else:
                if code > 122:
                    code = 97 + (code - 123)
                elif code < 97:
                    code = 122 - (96 - code)
            cipher += chr(code)
        else:
            cipher += char
    return cipher
```
Remember, a true Enigma is far more complex!

